CREATE TABLE [dbo].[Car_Sales_Details]
(
    VIN VARCHAR(50),
    Buyer_Name VARCHAR(50),
    Buyer_Gender VARCHAR(10),
    Buyer_Age INT,
    Buyer_City VARCHAR(50),
    Buyer_State VARCHAR(50),
    Loan_Taken VARCHAR(10),
    Sell_Date DATE,
    Dealer_Name VARCHAR(50),
    updated_at DATETIME DEFAULT GETDATE(),

    FOREIGN KEY (VIN) References Car_Details(VIN)
);

